def find_minimal_edit(s_in: str, s_out: str) -> tuple[str, str, int]:
    """
    Find the minimal edit: what substring changes to what and where.
    """
    # Find first difference
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Find the longest matching prefix and suffix to determine the substring being replaced
            # For simplicity, we'll look at character-level differences
            old_char = s_in[i]
            new_char = s_out[i]
            return old_char, new_char, i

    # If we get here, one string is a prefix of the other
    if len(s_in) < len(s_out):
        # Insertion case
        return "", s_out[len(s_in)], len(s_in)
    else:
        # Deletion case  
        return s_in[len(s_out)], "", len(s_out)

# Analyze the changed pairs
changed = [(0, 'jcd', 'jcdd'), (3, 'kdcyz', 'kkyz')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}'")
    print(f"  Change at position {pos}: '{old_sub}' -> '{new_sub}'")

