                    print(f"    Character '{inp[j]}' -> '{outp[j]}'")
                elif j >= len(inp):
                    print(f"    Inserted character '{outp[j]}'")
                elif j >= len(outp):
                    print(f"    Deleted character '{inp[j]}'")
